import {CHARS,STATS,SHIFTS} from './data.mjs';
import {MAX_TURNS,initialState,available,planJob,startShift,dispatchJob,tick,grade} from './engine.mjs';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const who=id=>id==='dispatch'?'调度员':CHARS.find(c=>c.id===id)?.name||'现场';
let state=initialState(),campaign={},selected=[],jobId=state.jobs[0].id,mode='safe',sound=true,modal='',resultQueue=[],toastTimer,audioContext,lastFocus;
const SAVE='abstract-dispatch-v1';
try{const v=JSON.parse(localStorage.getItem(SAVE));if(v?.version===1&&Number.isInteger(v.state?.shift)&&v.state.shift>=0&&v.state.shift<SHIFTS.length&&v.state.jobs?.length===4&&v.state.jobs.every(j=>SHIFTS[v.state.shift].jobs.some(a=>a.id===j.id))&&v.state.duty?.every(id=>CHARS.some(c=>c.id===id))){state=v.state;campaign=v.campaign||{};jobId=state.jobs.find(j=>j.status==='waiting')?.id||state.jobs[0].id;sound=v.sound!==false;}}catch{}
function save(){try{localStorage.setItem(SAVE,JSON.stringify({version:1,state,campaign,sound}));}catch{}}
function beep(type='click'){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.type='sine';const t=audioContext.currentTime;o.frequency.setValueAtTime(type==='send'?660:type==='done'?440:330,t);o.frequency.exponentialRampToValueAtTime(type==='send'?990:220,t+.1);g.gain.setValueAtTime(.035,t);g.gain.exponentialRampToValueAtTime(.001,t+.15);o.start();o.stop(t+.16);}catch{}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function icon(name,size=20){const paths={lift:'<rect x="5" y="3" width="14" height="18" rx="1"/><path d="M12 3v18M9 8l-2 2 2 2m6-4 2 2-2 2"/>',fire:'<path d="M13 2c2 6 7 7 6 13-1 8-14 9-14 0 0-3 2-6 4-8 0 3 1 4 2 4 3-3 2-6 2-9Z"/>',crowd:'<circle cx="12" cy="7" r="3"/><path d="M6 21v-4a6 6 0 0 1 12 0v4M3 9a3 3 0 0 0 0 6m18-6a3 3 0 0 1 0 6"/>',drone:'<path d="M9 9h6v6H9ZM9 9 5 5m10 4 4-4M9 15l-4 4m10-4 4 4"/><circle cx="4" cy="4" r="2"/><circle cx="20" cy="4" r="2"/><circle cx="4" cy="20" r="2"/><circle cx="20" cy="20" r="2"/>',screen:'<rect x="3" y="3" width="18" height="13" rx="1"/><path d="M12 16v5m-5 0h10m-9-14 3 3-3 3m5 0h3"/>',bridge:'<path d="M2 16h20M4 16V5m16 11V5M4 8c4 6 12 6 16 0M8 12v4m8-4v4M2 20h20"/>',stage:'<path d="M3 17h18v4H3ZM7 17V9m10 8V9M4 3h16l-3 6H7Z"/><circle cx="12" cy="12" r="2"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.crowd}</svg>`;}
function clock(turn=state.turn){return `20:${String(turn*10).padStart(2,'0')}`;}
function status(c){if(!state.duty.includes(c.id))return ['休班','offduty'];const j=state.jobs.find(j=>j.status==='active'&&j.crew.includes(c.id));if(j)return [`出勤 · ${j.remaining}拍`,'busy'];if((state.returnAt[c.id]||0)>state.turn)return ['返程 · 1拍','busy'];return [state.started?'待命':'值班',''];}
function render(){
 const shift=SHIFTS[state.shift],job=state.jobs.find(j=>j.id===jobId)||state.jobs[0],plan=selected.length&&job.status==='waiting'?planJob(job,selected,mode):null;
 const active=state.jobs.filter(j=>j.status==='active').length,late=plan&&state.turn+plan.duration>job.deadline;
 $('#app').innerHTML=`<div class="shell">
 <header class="topbar"><div class="brand"><div class="brand-mark">派</div><div><h1>抽象派遣局</h1><small>ODD JOBS. ODDER PEOPLE.</small></div></div><nav class="nav" aria-label="主导航"><button class="active" data-action="board">调度台</button><button data-action="archive">人员档案 <span style="font:9px var(--mono);opacity:.6">08</span></button><button data-action="history">事故回放</button></nav><div class="top-right"><span class="online"><i></i>全员精神状态在线</span><button class="mini-btn" data-action="sound" aria-label="${sound?'关闭音效':'开启音效'}">${sound?'♪ 音效开':'♪ 音效关'}</button><button class="mini-btn" data-action="help">怎么玩 ↗</button></div></header>
 <section class="masthead"><div><div class="eyebrow">NIGHT SHIFT 0${state.shift+1} / 03 · ${esc(shift.subtitle)} <button class="clean shift-link" data-action="choose-shift">换班 ↗</button></div><div class="headline"><h2>${esc(shift.name)}</h2><span class="stamp">试 营 业</span></div><p class="intro">${esc(shift.brief)}</p><div class="mobile-controls"><button class="mini-btn" data-action="help">怎么玩 ↗</button><button class="mini-btn" data-action="sound">${sound?'♪ 关音效':'♪ 开音效'}</button></div></div><div class="metrics"><div class="metric"><label>本班预算</label><strong class="acid">${state.budget}</strong><small>点</small></div><div class="metric"><label>解决事件</label><strong>${state.completed}<small>/ 4</small></strong></div><div class="metric"><label>群众满意</label><strong>${state.reputation}<small>%</small></strong></div><div class="metric"><label>节目效果</label><strong>${String(state.effect).padStart(2,'0')}</strong></div></div></section>
 <main class="workspace"><section class="left-col"><div class="section-head"><h3>${state.started?'出勤人员':'先选6人值班'}</h3><small>${state.started?`${state.duty.filter(id=>available(state,id)).length} READY`:`${state.duty.length} / 6 ON DUTY`}</small></div><div class="roster">${CHARS.map((c,i)=>{const [label,cl]=status(c);const chosen=state.started?selected.includes(c.id):state.duty.includes(c.id);return `<article class="person ${cl} ${chosen?'selected':''}" style="--c:${c.color}" role="button" tabindex="0" data-action="person" data-id="${c.id}" aria-label="${c.name}，${label}，${state.started?'选择出勤':'切换值班'}" aria-pressed="${chosen}"><div class="portrait"><span class="badge ${cl?'':'duty'}">${label}</span>${chosen?'<span class="tick">✓</span>':''}<img src="./assets/${c.id}.webp" alt="${c.name}美漫角色立绘" ${i>3?'loading="lazy"':''}></div><div class="info"><div class="name-row"><strong>${c.name}</strong><button class="clean number" data-action="profile" data-id="${c.id}" aria-label="查看${c.name}档案">↗</button></div><div class="tagline">${c.title}</div><div class="pips">${Array.from({length:5},(_,i)=>`<span class="${i<Math.max(...Object.values(c.stats))?'on':''}"></span>`).join('')}</div></div></article>`}).join('')}</div><div class="roster-tip">${state.started?'点人物选出勤，点 ↗ 看技能。每单最多2人。<br>任务完成后返程1拍，才可再次出勤。':'默认已排好6人。点卡片换班，点 ↗ 看技能。<br>准备好后，按下「开始夜班」。'}</div></section>
 <section class="center-col"><div class="section-head"><h3>抽象区实时地图</h3><small>${active} / 2 IN PROGRESS</small></div><div class="map-wrap"><div class="map-kicker">SECTOR 07 / LIVE<strong>抽 象 区</strong></div>${citySvg()}${state.jobs.map((j,i)=>`<button class="pin ${j.status} ${job.id===j.id?'current':''}" style="left:${j.point[0]}%;top:${j.point[1]}%" data-action="job" data-id="${j.id}" aria-label="选择任务：${esc(j.title)}">${j.status==='done'?'✓':icon(j.type)}</button><span class="pin-label" style="left:${j.point[0]}%;top:${j.point[1]}%">${esc(j.where)}</span>`).join('')}<div class="map-legend"><span><i></i>待处理</span><span><i style="background:var(--cyan)"></i>出勤中</span><span><i class="green"></i>已解决</span></div><div class="map-corner">✦ N &nbsp; ━ 200m</div></div>
 <section class="dispatch-panel" aria-label="任务派遣"><div class="dispatch-top"><div><div class="eyebrow">CASE ${String(state.jobs.indexOf(job)+1).padStart(2,'0')} / ${esc(job.where)}</div><h3>${esc(job.title)}</h3></div><div class="deadline">${job.status==='waiting'?`剩 ${Math.max(0,job.deadline-state.turn)} 拍`:job.status==='active'?`处理中 · ${job.remaining}拍`:{done:'已解决 ✓',failed:'这波寄了',expired:'客户已撤单'}[job.status]}</div></div><p class="job-desc">${esc(job.desc)}</p>
 ${job.status==='waiting'?`<div class="routes">${['safe','chaos'].map(m=>`<button class="route ${mode===m?'active':''}" data-action="route" data-mode="${m}"><strong><i class="marker"></i>${m==='safe'?'稳妥处理':'放飞自我'}</strong>${esc(job[m].name)}</button>`).join('')}</div><div class="requirements">${Object.entries(job[mode].req).map(([k,v])=>`<span class="req ${plan?(plan.stats[k]>=v?'ok':'bad'):''}">${STATS[k]} ${plan?plan.stats[k]+' / ':''}${v}${plan?(plan.stats[k]>=v?' ✓':' ✕'):''}</span>`).join('')}<span>基础耗时 ${job[mode].duration}拍</span></div><div class="crew-row"><div class="crew-chips">${selected.length?selected.map(id=>`<button class="crew-chip" data-action="person" data-id="${id}">${who(id)} ×</button>`).join(''):'← 点左侧人物，最多选2位'}</div><span style="font:10px var(--mono);color:var(--muted)">${selected.length}/2</span></div>${plan?`<div class="plan-row"><span>到场处理 <b>${plan.duration}拍</b></span><span>出勤费 <b>${plan.fee}</b></span><span>成功奖金 <b>+${job.pay}</b></span><span>预计损失 <b>−${plan.damage}</b></span><span style="color:${plan.success?'var(--acid)':'var(--coral)'}">${plan.success?'能力达标 ✓':'能力不足，预计失败'}</span></div><p class="perks">${plan.perks.length?plan.perks.map(esc).join(' · '):'普通出勤，无额外技能修正。'}</p>`:'<div class="plan-row">选人后查看实际耗时、费用和成功条件。</div>'}<button class="dispatch-btn" data-action="dispatch" ${!state.started||!selected.length||active>=2||late||plan?.fee>state.budget||state.finished?'disabled':''}><span>${!state.started?'先开始夜班':active>=2?'已有两单在处理中':late?'赶不上期限，换个组合':plan?.fee>state.budget?'预算不足':!selected.length?'选好人再出发':plan&&!plan.success?'硬着头皮上':'就你们了，出发！'}</span><span>↗</span></button>`:job.status==='active'?`<div class="history-banner">${job.crew.map(who).join(' ＋ ')} 正在现场处理「${esc(job.plan.name)}」。<br>推进时间后才会结算；这段时间可以安排另一单。</div><button class="mini-btn" style="margin-top:14px" data-action="recall" data-id="${job.id}">召回重派 · 出勤费不退，返程1拍</button>`:`<div class="history-banner">${job.status==='done'?`任务已完成，获得${job.plan.pay}预算。${job.plan.damage?'设备损失'+job.plan.damage+'预算。':'没有设备损失。'}`:job.status==='failed'?'这单没干成。换个搭配，重开本班可以再试。':'期限已过，下次先处理更着急的。'}</div>${job.status!=='expired'?`<button class="mini-btn" style="margin-top:14px" data-action="replay" data-id="${job.id}">重看现场 ↻</button>`:''}`}</section></section>
 <aside class="right-col"><section class="tickets"><div class="section-head"><h3>待办，没一件省心</h3><small>04 CASES</small></div>${state.jobs.map((j,i)=>`<button class="ticket ${j.status} ${j.id===jobId?'current':''}" data-action="job" data-id="${j.id}"><div class="ticket-top"><span>NO. ${String(i+1).padStart(3,'0')} / ${esc(j.where)}</span><span class="${j.status==='waiting'&&j.deadline-state.turn<=2?'urgent':''}">${j.status==='waiting'?'◷ '+Math.max(0,j.deadline-state.turn)+'拍内':''}</span></div><strong>${esc(j.title)}</strong><div class="ticket-bottom"><span class="status-${j.status}">${j.status==='active'?j.crew.map(who).join(' / '):{waiting:j.tags.join(' · '),done:'✓ 已解决',expired:'× 超时撤单',failed:'× 任务失败'}[j.status]}</span><span>${j.status==='waiting'?'奖励 +'+j.pay:j.status==='active'?'剩 '+j.remaining+'拍':''}</span></div>${j.status==='active'?`<div class="progress-track"><div style="width:${100*(1-j.remaining/j.plan.duration)}%"></div></div>`:''}</button>`).join('')}</section><section class="radio"><div class="radio-head">◉ 对讲机 <span><i class="live-dot"></i> CH. 07</span></div><div class="radio-log" role="log" aria-live="polite">${state.log.length?state.log.slice(-6).map(l=>`<div class="radio-line"><time>${clock(l.turn)} / INCOMING</time><span class="speaker">${who(l.speaker)}</span>${esc(l.text)}</div>`).join(''):'<div class="radio-empty">滋——<br>频道已接通。等一个敢来上班的人。</div>'}</div><div class="help-note">◈ 真把活干完，才算成功。<br>节目效果再高，也不能抵扣任务失败。</div></section></aside></main>
 </div><footer class="bottom-bar"><div class="bottom-inner"><div class="clock"><div><strong>${clock()}</strong><span>第 ${Math.min(state.turn+1,6)} / 6 拍 · 每拍10分钟</span></div><div class="beats">${Array.from({length:6},(_,i)=>`<span class="beat ${i<state.turn?'filled':''}"></span>`).join('')}</div></div><div class="bottom-info">${!state.started?'每班6人 · 同时接2单 · 每单最多2人':state.finished?'夜班已结束。明天的事，明天再背锅。':active?`${active}单正在处理。推进时间，查看现场结果。`:'还有待办。可以先派人，再推进时间。'}</div><div><button class="main-cta" data-action="advance" ${!state.started&&state.duty.length!==6?'disabled':''}><span>${!state.started?'开始夜班':state.finished?'查看本班结算':'推进一拍'}</span><span class="arrow">${state.finished?'↗':'→'}</span></button><div class="shortcut">SPACE / ${state.started?'推进时间':'开始夜班'}</div></div></div></footer>`;
 const log=$('.radio-log');if(log)log.scrollTop=log.scrollHeight;save();
}
function citySvg(){
 const blocks=[[110,96,92,61],[242,72,110,77],[405,72,63,72],[514,85,112,64],[70,214,100,65],[229,197,96,57],[398,194,110,64],[558,216,74,59],[82,341,89,58],[221,333,111,63],[398,336,85,55],[553,341,70,57]];
 const buildings=blocks.map(([x,y,w,h],i)=>`<g><path d="M${x+7} ${y+7}h${w}v${h}h-${w}Z" fill="#121c17"/><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${i%3===0?'#45523e':'#354333'}" stroke="#68765a" stroke-width="1"/><path d="M${x+8} ${y+9}h${w-16}v${h-18}h-${w-16}Z" fill="none" stroke="#798568" stroke-width=".6"/>${Array.from({length:Math.floor(w/17)},(_,j)=>`<path d="M${x+12+j*17} ${y+14}v${h-28}" stroke="#68765a" stroke-width="3" opacity=".5"/>`).join('')}</g>`).join('');
 return `<svg class="city" viewBox="0 0 700 470" preserveAspectRatio="none" aria-label="抽象区地图"><defs><pattern id="grid" width="23" height="23" patternUnits="userSpaceOnUse"><path d="M23 0H0V23" fill="none" stroke="#738265" stroke-width=".3" opacity=".23"/></pattern><pattern id="halftone" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#afbc8c" opacity=".14"/></pattern></defs><rect width="700" height="470" fill="#263328"/><rect width="700" height="470" fill="url(#grid)"/><path d="M0 84C110 135 30 200 13 252S70 440 0 470" fill="none" stroke="#4d6d69" stroke-width="54"/><path d="M0 84C110 135 30 200 13 252S70 440 0 470" fill="none" stroke="#7d9f8c" stroke-width="1" stroke-dasharray="5 5"/><path d="M0 174H700M0 308H700M199 0V470M365 0V470M530 0V470" stroke="#1c261e" stroke-width="29"/><path d="M0 174H700M0 308H700M199 0V470M365 0V470M530 0V470" stroke="#b4bd8e" stroke-width="1" stroke-dasharray="6 10" opacity=".3"/>${buildings}<g fill="#708253" stroke="#a2ad79" stroke-width="1"><circle cx="126" cy="285" r="8"/><circle cx="150" cy="287" r="6"/><circle cx="627" cy="328" r="8"/><circle cx="649" cy="352" r="6"/><circle cx="611" cy="414" r="8"/><circle cx="642" cy="414" r="6"/><circle cx="73" cy="316" r="7"/></g><rect x="92" y="355" width="67" height="33" fill="url(#halftone)"/><g font-family="sans-serif" font-size="9" fill="#a4b28c" opacity=".7"><text x="275" y="178">摸 鱼 路</text><text x="405" y="311">不 想 干 街</text><text x="206" y="370" transform="rotate(-90 206 370)">加 班 大 道</text><text x="558" y="155">南 门 商 场</text></g><path d="M320 434h90v-25h-90Z" fill="#dfec85" stroke="#11190f" stroke-width="2"/><text x="365" y="425" text-anchor="middle" font-size="11" font-weight="bold" fill="#242b1f">派遣局 / HQ</text>${state.jobs.filter(j=>j.status==='active').map(j=>`<path d="M365 410L365 ${j.point[1]*4.7}L${j.point[0]*7} ${j.point[1]*4.7}" fill="none" stroke="#88cbd0" stroke-width="2" stroke-dasharray="5 6" opacity=".8"/>`).join('')}<path d="M650 55v-23m-5 9 5-10 5 10" stroke="#afba8b" stroke-width="1.5" fill="none"/></svg>`;
}
function openModal(html,kind='generic'){lastFocus=document.activeElement;modal=kind;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${kind==='scene'?'现场回放':kind==='summary'?'夜班结算':'派遣局资料'}" tabindex="-1">${html}<button class="close-btn" data-action="close" aria-label="关闭">×</button></section></div>`;$('.modal').focus();document.body.style.overflow='hidden';}
function closeModal(){const was=modal;modal='';$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus?.();if(was==='scene')showNextResult();}
function archive(){openModal(`<div class="modal-body"><div class="eyebrow">PERSONNEL FILES / 08</div><h2>履历很满，<br>靠谱另算。</h2><p>点开档案看技能。强的人不一定适合这单，话多的人也能派上用场。</p><div class="archive-grid">${CHARS.map(c=>`<button class="archive-card" data-action="profile" data-id="${c.id}" style="background:${c.color}"><img src="./assets/${c.id}.webp" alt="${c.name}"><div><strong>${c.name}</strong><small>${c.title} / ${c.skill}</small></div></button>`).join('')}</div><small style="font-size:10px;color:#626957">虚构角色 · 荒诞喜剧试玩 · 人物与台词尚在打磨</small></div>`,'archive');}
function profile(id){const c=CHARS.find(c=>c.id===id);if(!c)return;openModal(`<div class="profile"><div class="profile-art" style="--c:${c.color}"><img src="./assets/${c.id}.webp" alt="${c.name}角色立绘"></div><div class="profile-info"><div class="eyebrow">EMPLOYEE / ${String(CHARS.indexOf(c)+1).padStart(3,'0')}</div><h2>${c.name}</h2><p>${c.title} &nbsp; / &nbsp; ${c.tags.join(' · ')}</p><div class="quote">“${c.quip}”</div><div class="stats-grid">${Object.entries(c.stats).map(([k,v])=>`<div><div class="stat-label"><span>${STATS[k]}</span><b>${v}/5</b></div><div class="stat-bar"><div style="width:${v*20}%"></div></div></div>`).join('')}</div><div class="skill-name">✦ ${c.skill}</div><div class="skill-text">${c.desc}</div><button class="mini-btn" style="margin-top:22px" data-action="archive">← 全员档案</button></div></div>`,'profile');}
function help(){openModal(`<div class="modal-body"><div class="eyebrow">NEW EMPLOYEE BRIEFING</div><h2>别慌，先把人派对。</h2><div class="help-list"><div class="help-step"><b>01</b><div><strong>选6人上班</strong><p>8个人里挑6个。每人的技能会改变耗时、能力或费用，点 ↗ 看详情。</p></div></div><div class="help-step"><b>02</b><div><strong>点地图选任务，再点人物</strong><p>每单1到2人，最多同时处理2单。能力要达标，时间也得赶得上。</p></div></div><div class="help-step"><b>03</b><div><strong>稳妥处理，或者放飞自我</strong><p>稳妥通常更省设备；放飞通常更快，但赔钱。看好派遣前的预估。</p></div></div><div class="help-step"><b>04</b><div><strong>推进一拍，看现场怎么收场</strong><p>任务完成拿奖金，人员再返程1拍。每班6拍、4单；超时会撤单。空格也能推进。</p></div></div></div><p>派出去了还能召回，但出勤费不退、人员也要返程。音效可以在顶部关闭。</p><button class="main-cta" data-action="close">懂了，先上班 <span>→</span></button></div>`,'help');}
function sceneSvg(type,chaos,success){
 const ink='#20261e',cream='#eee9da',green='#cbd49d',red='#dc977d';
 const person=(x,y,c=ink)=>`<g transform="translate(${x} ${y})"><circle cx="0" cy="0" r="9" fill="${cream}" stroke="${ink}" stroke-width="3"/><path d="M-8 13h16l5 29h-26Z" fill="${c}" stroke="${ink}" stroke-width="3"/><path d="M-7 41l-4 24m18-24 4 24m-19-45-18 15m34-15 15 13" stroke="${ink}" stroke-width="4" fill="none"/></g>`;
 let shapes='';
 if(type==='lift')shapes=`<path d="M150 250V40h400v210" fill="#c2c6ac" stroke="${ink}" stroke-width="5"/><path d="M${chaos?180:205} 250V70h290v180" fill="#717d64" stroke="${ink}" stroke-width="5"/><g class="${chaos?'chaos-move':''}"><rect x="${chaos?360:230}" y="${chaos?100:92}" width="200" height="158" fill="${cream}" stroke="${ink}" stroke-width="5"/><path d="M${chaos?460:330} ${chaos?100:92}v158" stroke="${ink}" stroke-width="4"/>${chaos?'<path d="M380 100V28h160v72" fill="none" stroke="#20261e" stroke-width="7"/>':''}</g>${person(chaos?300:285,161)}${person(chaos?585:395,161,red)}<text x="200" y="52" font-size="16" font-weight="bold" fill="${ink}">03 F / 摸鱼大厦</text>`;
 else if(type==='fire')shapes=`<rect x="176" y="77" width="370" height="173" fill="${cream}" stroke="${ink}" stroke-width="5"/><path d="M155 77h412l-28-43H182Z" fill="${green}" stroke="${ink}" stroke-width="5"/><rect x="204" y="116" width="100" height="100" fill="#7d8c77" stroke="${ink}" stroke-width="4"/><rect x="360" y="116" width="100" height="134" fill="#7d8c77" stroke="${ink}" stroke-width="4"/><text x="361" y="65" text-anchor="middle" font-size="21" font-weight="900" fill="${ink}">吨 吨 奶 茶</text><g class="chaos-move"><path d="M260 145q-50-60 0-88-4 25 21 32 10-23 4-46 75 81 25 109Z" fill="${red}" stroke="${ink}" stroke-width="4"/></g><path d="M100 214Q240 39 460 169" fill="none" stroke="#79bac1" stroke-width="${chaos?36:13}" stroke-linecap="round" opacity=".9"/>${person(120,166)}${chaos?'<path d="M370 250l-13-69 56 29 31-51 38 91" fill="#c2c6ac" stroke="#20261e" stroke-width="4"/>':''}`;
 else if(type==='drone')shapes=`<path d="M385 250V74" stroke="${ink}" stroke-width="25"/><g class="${chaos?'chaos-move':''}" fill="${green}" stroke="${ink}" stroke-width="4"><circle cx="330" cy="85" r="54"/><circle cx="422" cy="77" r="64"/><circle cx="385" cy="34" r="42"/></g><path d="M385 80v67" stroke="${ink}" stroke-width="3"/><rect x="360" y="140" width="50" height="40" fill="${red}" stroke="${ink}" stroke-width="4"/><path d="M372 140v-13h25v13" fill="none" stroke="${ink}" stroke-width="3"/>${person(240,173)}${person(512,173,red)}<path d="M240 194 385 105" stroke="${ink}" stroke-width="3" stroke-dasharray="6 5"/>`;
 else if(type==='bridge')shapes=`<path d="M0 185h700v95H0Z" fill="#80b2ae"/><path d="M0 215q35-12 70 0t70 0t70 0t70 0t70 0t70 0t70 0t70 0t70 0t70 0" fill="none" stroke="${cream}" stroke-width="3"/><g class="${chaos?'chaos-move':''}"><path d="M125 ${chaos?112:181}h450" stroke="${ink}" stroke-width="24"/><path d="M145 ${chaos?112:181}v-100m410 100v-100M145 ${chaos?45:95}q200 140 410 0" fill="none" stroke="${ink}" stroke-width="6"/>${person(280,chaos?30:100,red)}${person(350,chaos?30:100)}</g>`;
 else if(type==='screen')shapes=`<path d="M180 250V40h370v210" fill="#a9b197" stroke="${ink}" stroke-width="5"/><rect x="202" y="60" width="325" height="155" fill="${ink}" stroke="${cream}" stroke-width="5"/><text x="362" y="130" text-anchor="middle" font-size="34" font-family="monospace" fill="${green}">${success?'CONNECTED':'ERROR 404'}</text><text x="362" y="166" text-anchor="middle" font-size="14" fill="${cream}">${chaos?'电闸：我下班了':'教程已加载完毕'}</text>${person(118,168)}${person(580,168,red)}${chaos?'<path d="M520 70l40-40 8 33 45-10-28 44" fill="#e1c368" stroke="#20261e" stroke-width="4"/>':''}`;
 else if(type==='stage')shapes=`<path d="M145 220h430v30H145Z" fill="${red}" stroke="${ink}" stroke-width="5"/><g class="${chaos?'chaos-move':''}"><path d="M210 ${chaos?125:200}h280v25H210Z" fill="${green}" stroke="${ink}" stroke-width="5"/>${person(350,chaos?42:117,red)}</g><path d="M155 220V36h410v184" fill="none" stroke="${ink}" stroke-width="8"/><path d="M177 36l43 37m302-37-43 37" stroke="#e4ae69" stroke-width="12"/><circle cx="220" cy="77" r="12" fill="${cream}" stroke="${ink}" stroke-width="4"/><circle cx="479" cy="77" r="12" fill="${cream}" stroke="${ink}" stroke-width="4"/><path d="M324 250h52l-8-30h-35Z" fill="${ink}"/>`;
 else shapes=`<rect x="138" y="50" width="420" height="155" fill="${cream}" stroke="${ink}" stroke-width="5"/><text x="348" y="90" text-anchor="middle" font-size="25" font-weight="900" fill="${ink}">${chaos?'今 天 全 场 包 圆':'请 有 序 排 队'}</text><path d="M138 125h420" stroke="${ink}" stroke-width="4"/>${[185,260,335,410,485].map((x,i)=>person(x,158,i%2?red:green)).join('')}<path d="M590 105l45-18v58l-45-18Z" fill="${red}" stroke="${ink}" stroke-width="4"/>`;
 return `<svg viewBox="0 0 700 270" aria-label="${success?'任务成功':'任务失败'}的漫画现场"><defs><pattern id="dots-scene" width="7" height="7" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#20261e" opacity=".12"/></pattern></defs><rect width="700" height="270" fill="#d9ddbd"/><rect width="700" height="270" fill="url(#dots-scene)"/><path d="M0 250h700" stroke="${ink}" stroke-width="5"/>${shapes}<path d="M40 30l77 24m500-16-53 27M45 109l55 3m546 45-57 1" stroke="${ink}" stroke-width="2" opacity=".5"/></svg>`;
}
function scene(r,replay=false){const caption=!r.success?'能力没凑齐，这单没干成。':r.mode==='safe'?'按计划完成。今天也能正常救人。':r.jobId==='lift'?'人出来了，电梯也出来了。':r.damage?'任务成功。设备先记在账上。':'这次居然没赔钱。';openModal(`<div class="scene-top"><div><div class="eyebrow">FIELD REPORT / ${clock(r.turn)}</div><h2>${esc(r.title)}</h2></div><span class="scene-stamp ${r.success?'':'fail'}">${r.success?'活干完了':'这波寄了'}</span></div><div class="scene-art ${r.mode==='chaos'?'chaos':''}">${['lift','fire'].includes(r.type)&&r.success?`<img class="painted-scene" src="./assets/scene-${r.type}-${r.mode}.webp" alt="${r.mode==='chaos'?'离谱方案':'稳妥方案'}的漫画现场">`:sceneSvg(r.type,r.mode==='chaos',r.success)}<span class="bang">${r.success?(r.mode==='chaos'?'轰！':'搞定。'):'啊？'}</span><div class="scene-crew">${r.crew.map(id=>`<img src="./assets/${id}.webp" alt="${who(id)}">`).join('')}</div><div class="scene-caption">${caption}</div></div><div class="dialogue">${r.lines.map(([id,t])=>`<div class="speech-line"><span class="who">${who(id)}</span><span>${esc(t)}</span></div>`).join('')}</div><div class="scene-foot"><small>${r.success?'成功奖金 +'+r.pay:'没有奖金'}　/　设备损失 −${r.damage}<br>人员返程1拍后可再次出勤。</small><button class="main-cta" data-action="close">${replay?'关掉回放':'继续派遣'} <span>→</span></button></div>`,replay?'replay':'scene');beep('done');}
function showNextResult(){if(resultQueue.length)scene(resultQueue.shift());else if(state.finished)summary();}
function summary(){
 const g=grade(state);campaign[state.shift]={completed:state.completed,effect:state.effect,damage:state.damage,budget:state.budget};save();
 openModal(`<div class="modal-body"><div class="eyebrow">SHIFT 0${state.shift+1} / END OF SHIFT</div><h2>${g}。</h2><p>${state.completed===4&&state.damage===0?'4单全清，设备也没赔。谁说咱们只能整活？':state.completed===4?'活是干完了。下次买设备，记得跟财务说一声。':state.completed>=2?'有几单漂亮，有几单需要集体失忆。换个搭配还能再试。':'人没怎么救到，会倒是先安排上了。重排人员再来一班。'}</p><div class="summary-grid"><div><span>任务完成</span><b>${state.completed}/4</b></div><div><span>设备损失</span><b>${state.damage}</b></div><div><span>剩余预算</span><b>${state.budget}</b></div><div><span>节目效果</span><b>${state.effect}</b></div></div><div class="result-list">${state.jobs.map(j=>`<div class="result-item"><span class="dot ${j.status==='done'?'':'bad'}"></span><span>${esc(j.title)}</span><span style="color:#69725c">${{done:'已解决',failed:'任务失败',expired:'超时撤单'}[j.status]||'未完成'}</span>${j.status!=='expired'&&j.plan?`<button data-action="replay" data-id="${j.id}">回放 ↗</button>`:''}</div>`).join('')}</div><div style="display:flex;gap:12px;flex-wrap:wrap"><button class="main-cta" data-action="next">${state.shift<2?'下一班，接着整':'三班已完，重新开局'} <span>→</span></button><button class="mini-btn" data-action="retry">重排人员，再试本班</button></div><div class="shift-select">${SHIFTS.map((s,i)=>`<button class="shift-btn ${i===state.shift?'current':''}" data-action="shift" data-shift="${i}">0${i+1} ${s.name}${campaign[i]?' · '+campaign[i].completed+'/4':''}</button>`).join('')}</div><p style="font-size:10px">全部3班，共12个任务。可以回到任意一班，试试不同的人员与处理方案。</p></div>`,'summary');
}
function history(){openModal(`<div class="modal-body"><div class="eyebrow">INCIDENT ARCHIVE</div><h2>谁的锅，<br>都有录像。</h2><p>这里只保存本班已结算的现场；看回放不会推进时间。</p><div class="result-list">${state.history.length?state.history.map(r=>`<div class="result-item"><span class="dot ${r.success?'':'bad'}"></span><span>${clock(r.turn)} · ${esc(r.title)}</span><button data-action="replay" data-id="${r.jobId}">看现场 ↗</button></div>`).join(''):'<p>还没出现场。先接一单，再回来看看你们干了什么。</p>'}</div><button class="mini-btn" data-action="close">← 回调度台</button></div>`,'history');}
function chooseShift(){openModal(`<div class="modal-body"><div class="eyebrow">PICK YOUR NEXT NIGHTMARE</div><h2>今晚挑点什么活？</h2><p>切换会重新开始该班；已经完成的班次成绩会保留。</p><div class="shift-select">${SHIFTS.map((s,i)=>`<button class="shift-btn ${i===state.shift?'current':''}" data-action="shift" data-shift="${i}">0${i+1} ${s.name}${campaign[i]?' · '+campaign[i].completed+'/4':''}</button>`).join('')}</div><div class="help-list"><p>第一夜：电梯、奶茶店、鸡蛋和树上的外卖。<br>第二夜：大屏、网红桥、仓库和树上的人。<br>第三夜：舞台、堵车、断电和难搞的客户。</p></div></div>`,'choose-shift');}
function newShift(index){state=initialState(index);jobId=state.jobs[0].id;selected=[];mode='safe';resultQueue=[];modal='';$('#modal-root').innerHTML='';document.body.style.overflow='';render();window.scrollTo({top:0,behavior:'smooth'});}
function action(el){const a=el.dataset.action,id=el.dataset.id;
 if(a==='sound'){sound=!sound;beep();render();return;}
 if(a==='choose-shift'){chooseShift();return;}if(a==='help'){help();return;}if(a==='archive'){archive();return;}if(a==='profile'){profile(id);return;}if(a==='history'){history();return;}if(a==='close'){closeModal();return;}if(a==='board'){if(modal)closeModal();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(a==='retry'){newShift(state.shift);return;}if(a==='next'){newShift((state.shift+1)%3);return;}if(a==='shift'){newShift(Number(el.dataset.shift));return;}
 if(a==='replay'){const r=state.history.find(r=>r.jobId===id);if(r)scene(r,true);return;}
 if(a==='person'){
  if(!state.started){if(state.duty.includes(id))state.duty=state.duty.filter(x=>x!==id);else if(state.duty.length<6)state.duty.push(id);else{toast('先让一位休班，再把他换上。');return;}}
  else {if(state.finished){profile(id);return;}if(!available(state,id)){const st=status(CHARS.find(c=>c.id===id));toast(who(id)+'还在'+st[0]+'。');return;}if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<2)selected.push(id);else{toast('每单最多2人，先取消一位。');return;}}
  beep();render();return;
 }
 if(a==='job'){jobId=id;beep();render();return;}if(a==='route'){mode=el.dataset.mode;beep();render();return;}
 if(a==='dispatch'){const r=dispatchJob(state,jobId,selected,mode);if(r.error){toast(r.error);return;}selected=[];const next=state.jobs.find(j=>j.status==='waiting');if(next)jobId=next.id;beep('send');render();toast(`${r.job.crew.map(who).join(' ＋ ')} 出发了，处理需要${r.plan.duration}拍。`);return;}
 if(a==='recall'){const j=state.jobs.find(j=>j.id===id);if(j?.status==='active'){const crew=[...j.crew];for(const c of crew)state.returnAt[c]=state.turn+1;j.status='waiting';j.crew=[];j.remaining=0;j.plan=null;state.log.push({turn:state.turn,speaker:'dispatch',text:`${crew.map(who).join('、')}已召回，出勤费不退。人员返程1拍。`});render();toast('已召回。人还在路上，下一拍才能重新派遣。');}return;}
 if(a==='advance'){if(!state.started){const error=startShift(state);if(error){toast(error);return;}beep('send');render();toast('夜班开始。选任务、选人，出发。');return;}if(state.finished){summary();return;}const results=tick(state);selected=selected.filter(id=>available(state,id));const next=state.jobs.find(j=>j.status==='waiting');if(next)jobId=next.id;beep();render();resultQueue=[...results];showNextResult();}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)action(el);else if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{
 if(modal){if(e.code==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const focusables=[...$('.modal').querySelectorAll('button:not(:disabled),[tabindex="0"]')];if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){e.preventDefault();first.focus();}}return;}
 if(e.code==='Space'&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)&&!e.target.closest('[data-action="person"]')){e.preventDefault();const el=$('[data-action="advance"]');if(el&&!el.disabled)action(el);}
 else if((e.key==='Enter'||e.code==='Space')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();action(e.target);}
});
render();
